+/**
+ * yt8824_sds_isolate_and_softreset_paged() - disable YT8824 serdes isolate
+ * and sds softreset.
+ * @phydev: a pointer to a &struct phy_device
+ *
+ * Returns: 0 or negative errno code
+ */
+static int yt8824_sds_isolate_and_softreset_paged(struct phy_device *phydev)
+{
+	unsigned int retry = 12;
+	int old_page;
+	int ret = -1;
+
+	old_page = phy_select_page(phydev, YT8824_RSSR_USXGMII_SPACE);
+	if (old_page < 0)
+		goto err_restore_page;
+
+	ret = __phy_read(phydev, MII_BMCR);
+	if (ret < 0)
+		return ret;
+
+	/* disable isolation */
+	ret &= ~BIT(10);
+	/* soft reset */
+	ret |= BMCR_RESET;
+	ret = __phy_write(phydev, MII_BMCR, ret);
+	if (ret < 0)
+		return ret;
+	do {
+		msleep(50);
+		ret = __phy_read(phydev, MII_BMCR);
+		if (ret < 0)
+			return ret;
+	} while ((ret & BMCR_RESET) && --retry);
+
+	if (ret & BMCR_RESET) {
+		ret = -ETIMEDOUT;
+		goto err_restore_page;
+	}
+
+err_restore_page:
+	return phy_restore_page(phydev, old_page, ret);
+}
